  "probability": 0.53,
  "range_low": 0.46,
  "range_high": 0.60,
  "summary": [
    "Anchor on base-rate risk (~12%) for state-actor chemical weapons use within a ~2-year horizon.",
    "OPCW CS detections on frontline Ukraine samples and intelligence warnings imply higher-than-anchor risk.",
    "Near-term forecasts (~12% within 12 months) support elevated risk through May 1, 2026.",
    "Deterrence and monitoring modestly offset risk, while escalation dynamics and attribution uncertainty keep the outcome uncertain."
  ],
  "confidence": "high",
  "narrative": "Base-rate anchor anchored near 12% is upweighted by frontline CS detections, credible warnings of expanded Russian use, and nonzero near-term forecasts; deterrence and attribution ambiguity still temper the estimate. The calibrated posterior is 53% with a +/- ~0.07 uncertainty range, suggesting meaningful but not definitive risk through May 1, 2026.",
  "justification": {
    "anchor": {
      "probability": 0.12,
      "basis": "Base-rate probability for state-actor chemical weapon use in contemporary interstate conflict within ~12–14 months; chosen as the reference class anchor for this horizon."
    },
    "factor_updates": [
      {
        "factor": "OPCW CS detections on frontline samples (Ukraine)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Independent lab confirmations of riot-control agent CS in Ukraine-frontline samples indicate chemical agents used in conflict, elevating baseline risk."
      },
      {
        "factor": "Russia's use described as standardized and commonplace by Dutch/German intelligence",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Intelligence suggesting ongoing, normalized use of banned chemical agents increases probability of a chemical-weapon incident within horizon."
      },
      {
        "factor": "Swift Centre near-term forecast for chemical/biological weapon use",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Forecast places nonzero near-term probability (≈12%), supporting elevated risk toward 2026-05-01."
      },
      {
        "factor": "International sanctions and OPCW monitoring exert deterrence",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Legal/normative pressures raise costs and reduce incentives, mitigating risk relative to the anchor."
      },
      {
        "factor": "Frontline escalation risk and ongoing conflict dynamics",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Increased hostilities can raise incentives to escalate with chemical agents."
      },
      {
        "factor": "Attribution uncertainty regarding CS findings",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Uncertainty about responsibility tempers reaction but does not remove risk."
      }
    ],
    "synthesis_rationale": "The posterior reflects a Bayesian aggregation of base-rate anchor with multiple correlated upward and downward updates. Upward signals (CS detections, intelligence risk, near-term forecasts, escalation risk) outweigh downward deterrence and attribution ambiguity, but acknowledged correlations and attribution uncertainties temper full confidence; calibration yields a mid-50s probability with a modest range."
  }
}

